import{_ as a,o,c as r,a0 as e}from"./chunks/framework.Caz7a20Z.js";const u=JSON.parse('{"title":"汇报差点气死我，但论文又升级了一轮","description":"昨天跟老师汇报差点气死——总揪着一些无关紧要的问题打转；不过今天又把论文升级了一轮，应该差不多了；明天全文润色、通读、找参考文献，希望明天能修改完成。","frontmatter":{"title":"汇报差点气死我，但论文又升级了一轮","date":"2026-09-15T00:00:00.000Z","tags":["日记"],"description":"昨天跟老师汇报差点气死——总揪着一些无关紧要的问题打转；不过今天又把论文升级了一轮，应该差不多了；明天全文润色、通读、找参考文献，希望明天能修改完成。"},"headers":[],"relativePath":"posts/diary-20260915.md","filePath":"posts/diary-20260915.md","lastUpdated":1789477694000}'),s={name:"posts/diary-20260915.md"};function n(i,t,p,l,d,h){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="汇报差点气死我-但论文又升级了一轮" tabindex="-1">汇报差点气死我，但论文又升级了一轮 <a class="header-anchor" href="#汇报差点气死我-但论文又升级了一轮" aria-label="Permalink to &quot;汇报差点气死我，但论文又升级了一轮&quot;">​</a></h1><p>今天先把昨天的火气倒一倒，再说说今天的进展 😮‍💨。</p><h2 id="昨天汇报-差点气死我" tabindex="-1">昨天汇报：差点气死我 <a class="header-anchor" href="#昨天汇报-差点气死我" aria-label="Permalink to &quot;昨天汇报：差点气死我&quot;">​</a></h2><p><strong>昨天跟老师汇报，差点气死我</strong> 😤。</p><p>不是说老师问得不对，而是那个过程太消耗了——<strong>老师总往一些无关紧要的细节上绕</strong>，真正关键的结论、核心的逻辑走向，反倒没怎么聊到。我在那儿讲主线，问题全在岔路上冒出来，一两个小时下来，感觉自己在对着空气挥拳。</p><p><strong>答非所问这一块</strong>，真的是让人抓狂。你要的是&quot;这个方向对不对&quot;&quot;这个结论站不站得住&quot;，回馈回来的却是&quot;这个图的坐标字体是不是再大一号&quot;。不是说细节不重要，但它不该占掉全部的注意力啊。</p><p>唉，气归气，回头想想也就那样。汇报嘛，本来就是各说各话的概率事件，遇上一次节奏完全对不上的，也只能认了。<strong>唉，就这样吧。</strong></p><h2 id="今天-论文又升级了一轮" tabindex="-1">今天：论文又升级了一轮 <a class="header-anchor" href="#今天-论文又升级了一轮" aria-label="Permalink to &quot;今天：论文又升级了一轮&quot;">​</a></h2><p>火气消化完，活儿还得干。<strong>今天又把论文进行了一轮升级</strong> 📈。</p><p>这轮不是小修小补，是真的往&quot;能看&quot;里推了一档——之前那些读着别扭的地方重写了，逻辑衔接不顺的地方理了，图表和正文的对应关系也重新捋了一遍。</p><p>改到现在这个程度，<strong>这样应该就挺好的了</strong>。不敢说完美，但至少自己通读下来不再皱眉头了，拿出来也不至于心虚。这一轮磨完，稿子的成色肉眼可见地不一样。</p><h2 id="明天-润色-通读-参考文献" tabindex="-1">明天：润色 + 通读 + 参考文献 <a class="header-anchor" href="#明天-润色-通读-参考文献" aria-label="Permalink to &quot;明天：润色 + 通读 + 参考文献&quot;">​</a></h2><p>明天的清单很具体，三件事：</p><ol><li><strong>全文润色</strong> ✍️——字句层面最后过一遍，把剩余的别扭表达扫干净。</li><li><strong>通读</strong> 📖——从头到尾顺下来，看整体节奏和连贯性。</li><li><strong>参考文献寻找</strong> 📚——该引的补上，格式统一，别在这个地方被挑刺。</li></ol><p><strong>希望明天能修改完成吧</strong> 🤞。</p><p>这轮改了这么久，战线拉得够长了，是真到了该收的时候。能不能明天画上句号不好说，但至少往那个方向冲一把。</p><h2 id="就这样" tabindex="-1">就这样 <a class="header-anchor" href="#就这样" aria-label="Permalink to &quot;就这样&quot;">​</a></h2><p>昨天汇报气不顺，今天论文升级了一轮，明天冲刺收尾。情绪有起伏，进度倒是一直在往前。</p><p>明天加油，争取把这轮修改彻底收掉 💪！</p>',19)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
